ars_trunc_exp_sample <- function(m, c, a, b, u = NULL) {
  if (is.null(u)) u <- runif(1)
  if (u < 0 || u > 1) stop("u must be in [0,1]")
  if (m == 0) {
    return(a + u * (b - a))
  }
  M <- m * (b - a)
  if (is.finite(M) && abs(M) < 700) {
    return(a + (1/m) * log1p(u * expm1(M)))
  }
  if (is.finite(M) && M > 0) {
    # large positive scale: sample near b
    return(b + (1/m) * log(u))
  }
  # M <= -700 or M = -Inf (m<0, b=Inf) or M=+Inf shouldn't reach
  if (!is.finite(M) && m > 0 && is.infinite(b)) {
    # degenerate (would have been caught); give error
    stop("non-integrable envelope piece (positive slope to +Inf)")
  }
  # For m<0 with M<=-700 or M=-Inf: expm1(M) ≈ -1 => log1p(-u)
  return(a + (1/m) * log1p(u * expm1(M)))
}
