    if (is.infinite(a) && m > 0) {
      # ∫_{-Inf}^b exp(mx+c) dx = exp(c + m b)/m
      return(c + m * b - log(m))
    }
    return(Inf)
  }
  if (M > 700) {
    return(c + m * b - log(m))   # m>0, mass dominated by upper end
  }
  return(c + m * a + log(abs(expm1(M))) - log(abs(m)))
}
