```r
check_distribution <- function(samples, exp_mean, exp_sd, alpha = 0.01, name = "dist") {
  n <- length(samples)
  m <- mean(samples); s <- sd(samples)
  # mean z-test
  z <- (m - exp_mean) / (s / sqrt(n))
  crit_z <- qnorm(1 - alpha/2)
  ok_mean <- abs(z) <= crit_z
  # sd Chi-square interval
  chi_low <- qchisq(alpha/2, df = n - 1)
  chi_high <- qchisq(1 - alpha/2, df = n - 1)
  var_low <- (n-1)*s^2 / chi_high
  var_high <- (n-1)*s^2 / chi_low
  ok_sd <- var_low <= exp_sd^2 && exp_sd^2 <= var_high
  detail <- sprintf("mean=%.4f sd=%.4f (expect %.4f, %.4f)", m, s, exp_mean, exp_sd)
  pass <- ok_mean && ok_sd
  list(pass=pass, mean=m, sd=s, ok_mean=ok_mean, ok_sd=ok_sd, detail=detail)
}
