ars_trunc_exp_sample <- function(m, c, a, b, u = NULL) {
  if (is.null(u)) u <- runif(1)
  if (u < 0 || u > 1) stop("u must be in [0,1]")
  if (m == 0) {
    if (!is.finite(b - a)) {
      if (is.infinite(b) && is.finite(a)) return(a + u * (b - a))  # Inf*tiny... eh
    }
    return(a + u * (b - a))
  }
  M <- m * (b - a)
  if (!is.finite(M)) {
    if (m > 0 && is.infinite(b)) {
      stop("Non-integrable envelope piece: positive slope extends to +Inf.")
    }
    if (m < 0 && is.infinite(a)) {
      stop("Non-integrable envelope piece: negative slope extends to -Inf.")
    }
    # m < 0, b = Inf  OR  m > 0, a = -Inf
    if (m < 0 && is.infinite(b)) {
      # density ∝ exp(m x) on [a, Inf): sample via inverse CDF
      return(a + (1 / m) * log1p(-u))
    }
    if (m > 0 && is.infinite(a)) {
      # density ∝ exp(m x) on (-Inf, b]
      return(b + (1 / m) * log(u))
    }
    return(a + u * (b - a))
  }
  if (M > 700) {
    return(b + (1 / m) * log(u))
  }
  return(a + (1 / m) * log1p(u * expm1(M)))
}
