ars_piece_logweight <- function(p) {
  m <- p$m; c <- p$c; a <- p$a; b <- p$b
  if (m == 0) {
    if (!is.finite(b - a)) stop("Non-integrable envelope piece (zero slope, infinite interval).")
    return(c + log(b - a))
  }
  M <- m * (b - a)
  if (!is.finite(M)) {
    if (m < 0 && is.infinite(b)) {
      return(c + m * a - log(-m))
    }
    if (m > 0 && is.infinite(a)) {
      return(c + m * b - log(m))
    }
    return(Inf)  # non-integrable; will be caught by tail checks
  }
  if (M > 700) {
    return(c + m * b - log(m))
  }
  return(c + m * a + log(abs(expm1(M))) - log(abs(m)))
}
