`lower_eval`:

```r
self$lower_eval <- function(x) {
  xs <- self$xs; hs <- self$hs
  n <- length(xs)
  if (n < 2) return(NULL)
  if (x < xs[1] || x > xs[n]) return(NULL)
  j <- min(findInterval(x, xs), n - 1)
  x0 <- xs[j]; x1 <- xs[j + 1]
  h0 <- hs[j]; h1 <- hs[j + 1]
  h0 + (h1 - h0) / (x1 - x0) * (x - x0)
}
```

`draw`:

```r
self$draw <- function() {
  repeat {
    self$build_upper()
    s <- ars_sample_envelope(self$upper_pieces)
    x <- s$x; ux <- s$ux
    if (is.nan(x) || x < self$lo || x > self$hi) next
    lx <- self$lower_eval(x)
    if (!is.null(lx)) {
      if (lx - ux >= log(runif(1))) return(x)
    }
    hx <- self$logd(x)
    if (!is.finite(hx) || is.nan(hx)) next
    if (hx > ux + self$tol) {
      stop(sprintf("Log-concavity violation at x = %g: h(x) = %g exceeds upper hull u(x) = %g. The provided density is not log-concave.", x, hx, ux))
    }
    if (runif(1) <= exp(hx - ux)) return(x)
    self$add_point(x, hx)
  }
}
```

