# ---------------------------------------------------------------------
# Utility: wrap the user's density into a log-density function.
# Accepts either an R function (e.g. dnorm) or a string expression such
# as "dnorm(x, mean=0, sd=1)".
# ---------------------------------------------------------------------
ars_logdensity <- function(density_function, use_log = FALSE) {
  if (is.character(density_function)) {
    expr <- paste0("function(x) ", density_function)
    density_function <- eval(parse(text = expr), envir = parent.frame())
  }
  if (!is.function(density_function)) {
    stop("density_function must be an R function (e.g., dnorm) or an expression string.")
  }
  force(density_function)
  if (isTRUE(use_log)) {
    function(x) density_function(x)
  } else {
    function(x) log(density_function(x))
  }
}


# ---------------------------------------------------------------------
# Module: numerical gradient of a log-density.
# Returns h'(x) for a vector x using central differences with a
# fallback to one-sided differences near domain boundaries.
# ---------------------------------------------------------------------
ars_num_gradient <- function(logd, xs) {
  step <- .Machine$double.eps^(1 / 3) * pmax(1, abs(xs))
  f_plus <- logd(xs + step)
  f_minus <- logd(xs - step)
  gr <- (f_plus - f_minus) / (2 * step)

  bad <- !is.finite(gr) | is.nan(gr)
  if (any(bad)) {
    step2 <- .Machine$double.eps^(1 / 4) * pmax(1, abs(xs))
    f0 <- logd(xs)
    f_f <- logd(xs + step2)
    f_b <- logd(xs - step2)
    gr_f <- (f_f - f0) / step2
    gr_b <- (f0 - f_b) / step2
    gr_f[!is.finite(gr_f)] <- NA_real_
    gr_b[!is.finite(gr_b)] <- NA_real_
    gr[bad] <- ifelse(is.finite(gr_f[bad]), gr_f[bad], gr_b[bad])
  }
  if (any(!is.finite(gr) | is.nan(gr))) {
    stop("Unable to compute derivative of the log-density at required points; ",
         "supply a gradient function via the 'gradient' argument.")
  }
  gr
}


# ---------------------------------------------------------------------
# Module: sample from a truncated exponential piece of the upper hull.
# The piece has density proportional to exp(m*x + c) on [a, b].
# ---------------------------------------------------------------------
ars_trunc_exp_sample <- function(m, c, a, b, u = NULL) {
  if (is.null(u)) u <- runif(1)
  if (u < 0 || u > 1) stop("u must be in [0, 1]")

  if (m == 0) {
    if (!is.finite(b - a)) {
      stop("Non-integrable envelope piece: zero slope on an infinite interval.")
    }
    return(a + u * (b - a))
  }

  M <- m * (b - a)

  if (!is.finite(M)) {
    # Handles the unbounded tails analytically.
    if (m < 0 && is.infinite(b)) {
      # exp(m x) on [a, Inf): inverse CDF gives  a + (1/m) log(1-u)
      return(a + (1 / m) * log1p(-u))
    }
    if (m > 0 && is.infinite(a)) {
      # exp(m x) on (-Inf, b]: inverse CDF gives  b + (1/m) log(u)
      return(b + (1 / m) * log(u))
    }
    if (m > 0 && is.infinite(b)) {
      stop("Non-integrable envelope piece: positive slope extends to +Inf.")
    }
    if (m < 0 && is.infinite(a)) {
      stop("Non-integrable envelope piece: negative slope extends to -Inf.")
    }
    return(a + u * (b - a))
  }

  if (M > 700) {
    # Numerically stable tail approximation for m > 0, large interval.
    return(b + (1 / m) * log(u))
  }

  # General stable inverse-CDF for a truncated exponential:
  #   x = a + (1/m) log(1 + u * (exp(m(b-a)) - 1))
  a + (1 / m) * log1p(u * expm1(M))
}


# ---------------------------------------------------------------------
# Module: log of the (unnormalized) mass of a single upper-hull piece,
# i.e. log(integral_a^b exp(m*x + c) dx).
# ---------------------------------------------------------------------
ars_piece_logweight <- function(p) {
  m <- p$m; c <- p$c; a <- p$a; b <- p$b
  if (m == 0) {
    if (!is.finite(b - a)) {
      stop("Non-integrable envelope piece: zero slope on an infinite interval.")
    }
    return(c + log(b - a))
  }
  M <- m * (b - a)
  if (!is.finite(M)) {
    if (m < 0 && is.infinite(b)) {
      # ∫_a^Inf exp(m x + c) dx = exp(c + m a) / |m|
      return(c + m * a - log(-m))
    }
    if (m > 0 && is.infinite(a)) {
      # ∫_{-Inf}^b exp(m x + c) dx = exp(c + m b) / m
      return(c + m * b - log(m))
    }
    return(Inf) # non-integrable; should be caught by the tail checks
  }
  if (M > 700) {
    # m > 0 and the interval is large: mass dominated by the upper end.
    return(c + m * b - log(m))
  }
  c + m * a + log(abs(expm1(M))) - log(abs(m))
}


# ---------------------------------------------------------------------
# Module: sample one point from the piecewise-exponential upper hull.
# Returns list(x, ux) where ux is the value of the upper hull at x.
# ---------------------------------------------------------------------
ars_sample_envelope <- function(pieces) {
  logw <- vapply(pieces, ars_piece_logweight, numeric(1))
  if (any(!is.finite(logw))) {
    stop("Upper hull contains a non-integrable/non-finite-mass piece.")
  }
  lmax <- max(logw)
  w <- exp(logw - lmax)
  k <- sample.int(length(pieces), size = 1, prob = w)
  p <- pieces[[k]]
  u <- runif(1)
  x <- ars_trunc_exp_sample(p$m, p$c, p$a, p$b, u)
  list(x = x, ux = p$m * x + p$c)
}


# ---------------------------------------------------------------------
# Module: locate the upper-hull piece that contains x.
# ---------------------------------------------------------------------
ars_find_piece <- function(x, pieces, tol = 1e-9) {
  for (i in seq_along(pieces)) {
    p <- pieces[[i]]
    if (x >= p$a - tol && x <= p$b + tol) return(i)
  }
  NA_integer_
}


# ---------------------------------------------------------------------
# Module: log-concavity check from derivatives.
# For a log-concave h, h'(x) must be non-increasing in x.
# ---------------------------------------------------------------------
ars_check_derivative_monotonicity <- function(self) {
  d <- self$ds
  if (length(d) >= 2) {
    if (any(d[-length(d)] < d[-1] - self$tol)) {
      stop("Log-concavity violation: the derivative of the log-density is not ",
           "non-increasing; the density does not appear to be log-concave.")
    }
  }
  invisible(self)
}


# ---------------------------------------------------------------------
# Module: evaluate a chord of the lower hull (linear interpolation of
# log-density between neighbouring abscissae). Returns NULL when x is
# outside the interval spanned by the abscissae (no squeeze available).
# ---------------------------------------------------------------------
ars_lower_eval <- function(xs, hs, x) {
  n <- length(xs)
  if (n < 2) return(NULL)
  if (x < xs[1] || x > xs[n]) return(NULL)
  j <- min(findInterval(x, xs), n - 1)
  x0 <- xs[j]; x1 <- xs[j + 1]
  h0 <- hs[j]; h1 <- hs[j + 1]
  h0 + (h1 - h0) / (x1 - x0) * (x - x0)
}


# ---------------------------------------------------------------------
# Default starting points when the user does not provide any.
# Heuristic only; users with unusual densities should supply points.
# ---------------------------------------------------------------------
ars_default_starting_points <- function(domain, logd) {
  lo <- domain[1]; hi <- domain[2]
  if (is.finite(lo) && is.finite(hi)) {
    n <- 4L
    return(lo + seq_len(n) * (hi - lo) / (n + 1))
  }
  if (!is.finite(lo) && !is.finite(hi)) {
    return(c(-1, 0, 1))
  }
  if (!is.finite(lo)) { # (-Inf, hi]
    if (hi < 0) return(hi + c(-1.5, -0.8, -0.3))
    return(c(-3, -1, -0.5))
  }
  # [lo, +Inf)
  if (lo >= 0) return(lo + c(0.1, 1, 3))
  lo + c(0.1, 1, 3)
}


# ---------------------------------------------------------------------
# State object for the ARS algorithm (environment-based OOP style).
# The returned environment holds the current set of abscissae and
# exposes the methods used during sampling.
# ---------------------------------------------------------------------
ars_state <- function(density_function, domain, initial_points = NULL,
                      use_log = FALSE, gradient = NULL,
                      tol = 1e-9, slope_tol = 1e-7, merge_tol = 1e-10) {
  self <- new.env(parent = emptyenv())
  self$logd <- ars_logdensity(density_function, use_log)
  self$lo  <- as.numeric(domain[1])
  self$hi  <- as.numeric(domain[2])
  self$gradient <- gradient
  self$tol <- tol
  self$slope_tol <- slope_tol
  self$merge_tol <- merge_tol

  if (is.null(initial_points)) {
    initial_points <- ars_default_starting_points(c(self$lo, self$hi), self$logd)
  }
  if (!is.numeric(initial_points)) stop("initial_points must be numeric.")
  xs <- sort(unique(as.numeric(initial_points)))
  xs <- xs[xs > self$lo & xs < self$hi]
  if (length(xs) == 0) {
    stop("No valid initial points strictly inside the domain.")
  }

  hs <- self$logd(xs)
  if (any(!is.finite(hs) | is.nan(hs))) {
    stop("The density is not positive and finite at all initial points; ",
         "choose different starting points.")
  }
  ds <- if (is.null(gradient)) ars_num_gradient(self$logd, xs) else gradient(xs)
  if (any(!is.finite(ds) | is.nan(ds))) {
    stop("Derivatives of the log-density at the initial points are not finite.")
  }

  self$xs <- xs
  self$hs <- hs
  self$ds <- ds
  self$n_added <- 0L

  # Initial log-concavity sanity check.
  ars_check_derivative_monotonicity(self)

  # -- methods ---------------------------------------------------------
  self$add_point <- function(x, hx = NULL) {
    if (any(abs(self$xs - x) < self$merge_tol)) return(invisible(self))
    if (is.null(hx)) hx <- self$logd(x)
    if (!is.finite(hx) || is.nan(hx)) return(invisible(self))
    dx <- if (is.null(self$gradient)) ars_num_gradient(self$logd, x) else self$gradient(x)
    if (!is.finite(dx) || is.nan(dx)) return(invisible(self))
    i <- findInterval(x, self$xs)
    self$xs <- append(self$xs, x, after = i)
    self$hs <- append(self$hs, hx, after = i)
    self$ds <- append(self$ds, dx, after = i)
    self$n_added <- self$n_added + 1L
    # Re-check log-concavity after every adaptation.
    ars_check_derivative_monotonicity(self)
    invisible(self)
  }

  self$build_upper <- function() {
    xs <- self$xs; hs <- self$hs; ds <- self$ds
    # Merge knots that describe the same (up to tolerance) tangent line.
    if (length(xs) >= 2) {
      keep <- c(TRUE, abs(diff(ds)) > self$slope_tol)
      xs <- xs[keep]; hs <- hs[keep]; ds <- ds[keep]
    }
    if (length(xs) == 0) stop("No knots available to build the upper hull.")

    n <- length(xs)
    m <- ds
    c <- hs - ds * xs

    # Breakpoints: intersections of adjacent tangents.
    z <- numeric(n - 1)
    if (n >= 2) {
      for (i in seq_len(n - 1)) {
        denom <- m[i] - m[i + 1]
        if (abs(denom) <= self$slope_tol) {
          stop("Degenerate parallel tangents in upper hull; density may not be log-concave.")
        }
        z[i] <- (c[i + 1] - c[i]) / denom
      }
      if (any(diff(z) <= 0)) {
        stop("Upper hull intersections are not strictly ordered; the density is not log-concave.")
      }
    }

    pieces <- vector("list", n)
    for (i in seq_len(n)) {
      a <- if (i == 1) self$lo else z[i - 1]
      b <- if (i == n) self$hi else z[i]
      pieces[[i]] <- list(a = a, b = b, m = m[i], c = c[i])
    }

    # Integrability of unbounded tails.
    if (is.infinite(self$lo) && m[1] <= 0) {
      stop("Log-concavity violation: the density is not integrable on the left ",
           "tail (log-density derivative must be positive at the leftmost point).")
    }
    if (is.infinite(self$hi) && m[n] >= 0) {
      stop("Log-concavity violation: the density is not integrable on the right ",
           "tail (log-density derivative must be negative at the rightmost point).")
    }

    self$upper_pieces <- pieces
    invisible(self)
  }

  self$upper_eval <- function(x) {
    pieces <- self$upper_pieces
    if (is.null(pieces)) stop("Upper hull has not been built yet.")
    k <- ars_find_piece(x, pieces, self$tol)
    if (is.na(k)) {
      stop(sprintf("Point %g falls outside the upper hull pieces.", x))
    }
    p <- pieces[[k]]
    p$m * x + p$c
  }

  self$lower_eval <- function(x) {
    ars_lower_eval(self$xs, self$hs, x)
  }

  self$draw <- function() {
    repeat {
      self$build_upper()
      s <- ars_sample_envelope(self$upper_pieces)
      x <- s$x; ux <- s$ux
      if (is.nan(x) || x < self$lo || x > self$hi) next

      # Squeeze test using the lower (chord) hull.
      lx <- self$lower_eval(x)
      if (!is.null(lx) && lx - ux >= log(runif(1))) {
        return(x)
      }

      # Full evaluation of the log-density.
      hx <- self$logd(x)
      if (!is.finite(hx) || is.nan(hx)) next

      # Log-concavity check: h must never exceed the upper hull.
      if (hx > ux + self$tol) {
        stop(sprintf("Log-concavity violation at x = %g: h(x) = %g exceeds upper ",
                     "hull u(x) = %g. The provided density is not log-concave.",
                     x, hx, ux))
      }

      if (runif(1) <= exp(hx - ux)) return(x)

      # Adaptation: add the rejected point to tighten the hull.
      self$add_point(x, hx)
    }
  }

  self
}


# ---------------------------------------------------------------------
# Main public function.
# ars(density_function, domain, n)
#   density_function : vectorized density function (or log-density when
#                      ... = list(use_log=TRUE)).
#   domain           : numeric vector of length 2, c(lower, upper);
#                      bounds may be -Inf / +Inf.
#   n                : number of samples to draw.
# Extra options can be passed via ...: initial_points, seed, gradient,
# use_log, tol, slope_tol, merge_tol.
# ---------------------------------------------------------------------
ars <- function(density_function, domain, n = 1000, ...) {
  dots <- list(...)

  # --- validate n ----------------------------------------------------
  if (is.null(n) || length(n) != 1 || !is.numeric(n) || is.na(n)) {
    stop("n must be a single numeric value (the number of samples to draw).")
  }
  if (n < 0) stop("n must be non-negative.")
  if (n != floor(n)) stop("n must be an integer.")
  n <- as.integer(n)

  # --- validate domain ------------------------------------------------
  if (!is.numeric(domain) || length(domain) != 2 || anyNA(domain)) {
    stop("domain must be a numeric vector of length 2, e.g. c(-Inf, Inf).")
  }
  if (domain[1] >= domain[2]) {
    stop("domain must satisfy lower bound < upper bound.")
  }

  # Optional seed for reproducibility.
  if (!is.null(dots$seed)) {
    if (!is.numeric(dots$seed) || length(dots$seed) != 1) {
      stop("seed must be a single numeric value.")
    }
    set.seed(as.integer(dots$seed))
  }

  st <- ars_state(
    density_function, domain,
    initial_points = dots$initial_points,
    use_log        = isTRUE(dots$use_log),
    gradient       = dots$gradient,
    tol            = if (is.null(dots$tol)) 1e-9 else dots$tol,
    slope_tol      = if (is.null(dots$slope_tol)) 1e-7 else dots$slope_tol,
    merge_tol      = if (is.null(dots$merge_tol)) 1e-10 else dots$merge_tol
  )

  if (n == 0) return(numeric(0))

  out <- numeric(n)
  for (i in seq_len(n)) out[i] <- st$draw()
  out
}


# =====================================================================
# Formal testing
# =====================================================================

# Helper used by the tests: check empirical mean/sd against known values
# using standard z and chi-squared confidence intervals.
check_distribution <- function(samples, exp_mean, exp_sd, alpha = 0.01) {
  n <- length(samples)
  m <- mean(samples)
  s <- sd(samples)

  z <- (m - exp_mean) / (s / sqrt(n))
  ok_mean <- abs(z) <= qnorm(1 - alpha / 2)

  chi_lo <- qchisq(alpha / 2, n - 1)
  chi_hi <- qchisq(1 - alpha / 2, n - 1)
  var_lo <- (n - 1) * s^2 / chi_hi
  var_hi <- (n - 1) * s^2 / chi_lo
  ok_sd <- var_lo <= exp_sd^2 && exp_sd^2 <= var_hi

  detail <- sprintf("mean=%.4f sd=%.4f (expected mean=%.3f sd=%.3f)",
                    m, s, exp_mean, exp_sd)
  list(pass = ok_mean && ok_sd, mean = m, sd = s, detail = detail)
}


test <- function() {
  cat("=== Adaptive Rejection Sampler: formal test suite ===\n")
  ok_all <- TRUE

  report <- function(name, passed, detail = "") {
    status <- if (passed) "PASS" else "FAIL"
    line <- sprintf("%s: %s", name, status)
    if (nzchar(detail)) line <- sprintf("%s  %s", line, detail)
    cat(line, "\n")
    if (!passed) ok_all <<- FALSE
    invisible(passed)
  }

  begin <- function(desc) cat("  Running:", desc, "...\n")

  # ------------------------------------------------------------------
  cat("\n--- Input validation ---\n")

  begin("negative sample count rejected")
  res <- tryCatch({ ars(dnorm, c(-Inf, Inf), n = -3); list(err = NULL) },
                  error = function(e) list(err = conditionMessage(e)))
  report("validate_negative_n",
         !is.null(res$err) && grepl("non-negative", res$err),
         if (is.null(res$err)) "no error thrown" else paste("error:", res$err))

  begin("non-integer sample count rejected")
  res <- tryCatch({ ars(dnorm, c(-Inf, Inf), n = 2.5); list(err = NULL) },
                  error = function(e) list(err = conditionMessage(e)))
  report("validate_noninteger_n",
         !is.null(res$err) && grepl("integer", res$err),
         if (is.null(res$err)) "no error thrown" else paste("error:", res$err))

  begin("zero sample count returns empty vector")
  res <- tryCatch({ z <- ars(dnorm, c(-Inf, Inf), n = 0);
                    list(err = NULL, val = z) },
                  error = function(e) list(err = conditionMessage(e)))
  report("validate_zero_n",
         is.null(res$err) && is.numeric(res$val) && length(res$val) == 0,
         "n=0 accepted")

  begin("invalid domain (lower >= upper) rejected")
  res <- tryCatch({ ars(dnorm, c(1, 0), 5); list(err = NULL) },
                  error = function(e) list(err = conditionMessage(e)))
  report("validate_domain_order",
         !is.null(res$err) && grepl("lower", res$err),
         if (is.null(res$err)) "no error thrown" else paste("error:", res$err))

  begin("invalid domain (wrong length) rejected")
  res <- tryCatch({ ars(dnorm, c(-Inf, Inf, 1), 5); list(err = NULL) },
                  error = function(e) list(err = conditionMessage(e)))
  report("validate_domain_length",
         !is.null(res$err) && grepl("length 2", res$err),
         if (is.null(res$err)) "no error thrown" else paste("error:", res$err))

  begin("invalid density object rejected")
  res <- tryCatch({ ars(42, c(-Inf, Inf), 5); list(err = NULL) },
                  error = function(e) list(err = conditionMessage(e)))
  report("validate_density_fn",
         !is.null(res$err) && grepl("R function", res$err),
         if (is.null(res$err)) "no error thrown" else paste("error:", res$err))

  begin("all-outside initial points rejected")
  res <- tryCatch({ ars(dnorm, c(0, 1), n = 5, initial_points = c(-1, 2));
                    list(err = NULL) },
                  error = function(e) list(err = conditionMessage(e)))
  report("validate_initial_points",
         !is.null(res$err) && grepl("initial", res$err),
         if (is.null(res$err)) "no error thrown" else paste("error:", res$err))

  begin("non-log-concave density (exp(x^2)) rejected")
  res <- tryCatch({ ars(function(x) exp(x^2), c(0, 1), n = 10); list(err = NULL) },
                  error = function(e) list(err = conditionMessage(e)))
  report("nonlogconcave_rejected_by_ars",
         !is.null(res$err) && grepl("log-concav", res$err, ignore.case = TRUE),
         if (is.null(res$err)) "no error thrown" else paste("error:", res$err))

  # ------------------------------------------------------------------
  cat("\n--- Module tests ---\n")

  begin("truncated-exponential sampler matches analytic means")
  set.seed(1)
  n_sim <- 200000
  s1 <- replicate(n_sim, ars_trunc_exp_sample(2, 0, 0, 1))
  s2 <- replicate(n_sim, ars_trunc_exp_sample(-1, 0, 0, 3))
  mu1 <- (exp(2) + 1) / (2 * (exp(2) - 1))          # m=2 on [0,1]
  mu2 <- (1 - 4 * exp(-3)) / (1 - exp(-3))           # m=-1 on [0,3]
  ok1 <- abs(mean(s1) - mu1) < 0.01
  ok2 <- abs(mean(s2) - mu2) < 0.01
  report("module_trunc_exp_sampler", ok1 && ok2,
         sprintf("m=2 mean=%.4f (expected %.4f); m=-1 mean=%.4f (expected %.4f)",
                mean(s1), mu1, mean(s2), mu2))

  begin("upper hull dominates log-density (normal)")
  st <- ars_state(dnorm, c(-Inf, Inf), initial_points = c(-1.5, -0.5, 0.5, 1.5))
  st$build_upper()
  xs <- seq(-6, 6, length.out = 601)
  hs <- st$logd(xs)
  us <- vapply(xs, st$upper_eval, numeric(1))
  viol <- max(hs - us)
  report("module_upper_hull_dominates", viol <= 1e-7,
         sprintf("max(h-u) = %.3e", max(hs - us)))

  begin("lower hull lies below log-density (normal)")
  st <- ars_state(dnorm, c(-Inf, Inf), initial_points = c(-1.5, -0.5, 0.5, 1.5))
  xs2 <- st$xs
  mids <- (xs2[-length(xs2)] + xs2[-1]) / 2
  ls <- vapply(mids, st$lower_eval, numeric(1))
  hs2 <- st$logd(mids)
  report("module_lower_hull_below", all(hs2 >= ls - 1e-7),
         sprintf("min(h-l) = %.3e", min(hs2 - ls)))

  begin("upper hull breakpoints are ordered (normal)")
  st <- ars_state(dnorm, c(-Inf, Inf), initial_points = c(-1.5, -0.5, 0.5, 1.5))
  st$build_upper()
  pieces <- st$upper_pieces
  a_vals <- vapply(pieces, function(p) p$a, numeric(1))
  b_vals <- vapply(pieces, function(p) p$b, numeric(1))
  ordered <- all(a_vals <= b_vals) && all(a_vals[-1] >= b_vals[-length(b_vals)])
  report("module_upper_hull_ordered", ordered,
         sprintf("piece intervals span [%g,%g]", a_vals[1], b_vals[length(b_vals)]))

  begin("hull checker detects non-log-concavity (bimodal density)")
  bimodal <- function(x) 0.5 * dnorm(x, mean = -3, sd = 1) + 0.5 * dnorm(x, mean = 3, sd = 1)
  st <- ars_state(bimodal, c(-Inf, Inf), initial_points = c(-4, 0, 4))
  st$build_upper()
  xs3 <- seq(-8, 8, length.out = 1001)
  hs3 <- st$logd(xs3)
  us3 <- vapply(xs3, st$upper_eval, numeric(1))
  viol3 <- max(hs3 - us3)
  report("nonlogconcave_hull_detected", viol3 > st$tol,
         sprintf("max(h-u) = %.3e (tol = %.1e)", viol3, st$tol))

  # ------------------------------------------------------------------
  cat("\n--- Distribution tests (stochastic; fixed seeds) ---\n")

  begin("normal N(0,1): sample 10000, compare mean and sd")
  set.seed(42)
  normal_sample <- ars(dnorm, c(-Inf, Inf), n = 10000, initial_points = c(-1.5, 0, 1.5))
  r <- check_distribution(normal_sample, 0, 1)
  report("normal_moments", r$pass, r$detail)

  begin("exponential rate=2: sample 10000, compare mean and sd")
  set.seed(7)
  exp_sample <- ars(function(x) dexp(x, rate = 2), c(0, Inf), n = 10000,
                    initial_points = c(0.1, 0.5, 1))
  r2 <- check_distribution(exp_sample, 0.5, 0.5)
  report("exponential_moments", r2$pass, r2$detail)

  # ------------------------------------------------------------------
  cat("\n--- Summary ---\n")
  cat("The adaptive rejection sampler test suite finished.",
      if (ok_all) "ALL TESTS PASSED." else "SOME TESTS FAILED.", "\n")
  invisible(ok_all)
}
"}

