    return(c(-1, 0, 1))
  }
  if (!is.finite(lo)) { # (-Inf, hi]
    if (hi < 0) return(hi + c(-1.5, -0.8, -0.3))
    return(c(-3, -1, -0.5))
  }
  # [lo, +Inf)
  if (lo >= 0) return(lo + c(0.1, 1, 3))
  lo + c(0.1, 1, 3)
}","new_string":"# ---------------------------------------------------------------------
# Helper: for unbounded domains, find points bracketing the mode so that
# the extreme tails have the right derivative signs:
#   * on a left tail extending to -Inf we need h'(x) > 0 at the leftmost
#     point;
#   * on a right tail extending to +Inf we need h'(x) < 0 at the
#     rightmost point.
# ---------------------------------------------------------------------
ars_bracket_tails <- function(logd, domain) {
  lo <- domain[1]; hi <- domain[2]

  # Choose an initial guess for the mode search.
  if (!is.finite(lo) && !is.finite(hi)) x0 <- 0
  else if (!is.finite(lo))            x0 <- if (hi > 0) 0 else hi - 1
  else if (!is.finite(hi))            x0 <- if (lo < 0) 0 else lo + 1
  else return(NULL)

  d0 <- tryCatch(ars_num_gradient(logd, x0), error = function(e) NA_real_)
  if (!is.finite(d0)) {
    if (!is.finite(lo) && !is.finite(hi)) return(c(-1, 0, 1))
    if (!is.finite(lo)) return(hi + c(-1.5, -0.8, -0.3))
    return(lo + c(0.1, 1, 3))
  }

  # --- left tail: need a point with h' > 0 --------------------------
  xl <- NULL
  if (is.infinite(lo)) {
    x <- x0; d <- d0; step <- 1
    if (is.finite(d) && d > 0) {
      xl <- x
    } else {
      for (i in seq_len(60)) {
        x <- x - step
        d <- tryCatch(ars_num_gradient(logd, x), error = function(e) NA_real_)
        step <- step * 2
        if (is.finite(d) && d > 0) { xl <- x; break }
      }
      if (is.null(xl)) xl <- x0 - 2
    }
  }

  # --- right tail: need a point with h' < 0 -------------------------
  xr <- NULL
  if (is.infinite(hi)) {
    x <- x0; d <- d0; step <- 1
    if (is.finite(d) && d < 0) {
      xr <- x
    } else {
      for (i in seq_len(60)) {
        x <- x + step
        d <- tryCatch(ars_num_gradient(logd, x), error = function(e) NA_real_)
        step <- step * 2
        if (is.finite(d) && d < 0) { xr <- x; break }
      }
      if (is.null(xr)) xr <- x0 + 2
    }
  }

  pts <- numeric(0)
  if (!is.null(xl)) pts <- c(pts, xl)
  pts <- c(pts, x0)
  if (!is.null(xr)) pts <- c(pts, xr)
  if (!is.null(xl) && !is.null(xr)) pts <- c(pts, (xl + xr) / 2)

  # Fill in a few extra interior points for half-bounded domains.
  if (is.null(xl) && is.finite(lo)) pts <- c(pts, lo + 1, x0 + 2)
  if (is.null(xr) && is.finite(hi)) pts <- c(pts, hi - 1, x0 - 2)

  unique(sort(pts))
}


# ---------------------------------------------------------------------
# Default starting points when the user does not provide any.
# For bounded domains we use a simple interior grid; for unbounded
# domains we bracket the mode so that the tail derivative conditions of
# the ARS upper hull are satisfied.
# ---------------------------------------------------------------------
ars_default_starting_points <- function(domain, logd) {
  lo <- domain[1]; hi <- domain[2]
  if (is.finite(lo) && is.finite(hi)) {
    n <- 4L
    return(lo + seq_len(n) * (hi - lo) / (n + 1))
  }
  ars_bracket_tails(logd, domain)
}"}

